import {ensureContinuity,advanceContinuity,ageLabel,residentVoice,continuityOptions,leaveThought} from './continuity.js';
import {perceive,studied,practicalOptions,unmet,note,pressure} from './interactions.js';
import {decide,rememberDecision} from './mind.js';
import {drawLivingWorld,drawActionEffects} from './living-world.js';
import {sceneOf,exits,locals,crossedExit,streetRoute} from './city.js';
import {drawCityMap} from './city-map.js';
import {W,H,places,boundary,walkable,canWalk,activePlaces,initialState,loadState,clock,commit,objective} from './world-model.js';
const $=id=>document.getElementById(id), canvas=$('world'),ctx=canvas.getContext('2d');
// Preserve the original storage key so existing worlds survive the Gutterlight rename.
const SAVE='mosslight.foundry.v1';let state;try{state=loadState(localStorage.getItem(SAVE));}catch{state=initialState();}
let width=innerWidth,height=innerHeight,scale=1,ox=0,oy=0,mode='watch',paused=false,keys=new Set(),path=[],destination=null,nearby=null,dir=0,moving=false,t=0,last=0,frame=0,autoWait=2,ambient=null,soundOn=false,speechUntil=0,toastTimer,saveTimer=0,focusRing=null;
ensureContinuity(state);advanceContinuity(state);
let pendingDecision=null,effects=[],perceptionClock=0,hovered=null;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const images={};const loads=['district','iona','items','crossing','lantern','violet','cable','boiler','blind','residents'].map(name=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[name]=im;resolve()};im.onerror=reject;im.src=`assets/${name}.png`;}));
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(SAVE,JSON.stringify(state));$('save-status').textContent='Local world · progress saved on this device';}catch{$('save-status').textContent='Storage unavailable · this visit will not be saved';}}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4200);}
function say(text){$('speech').textContent=text;$('speech').hidden=false;speechUntil=t+6;}
function perform(type,payload={}){const previousZone=state.zone;const event=commit(state,type,payload);if(!event)return false;if(['rummage','wind-wire','light-lamp','restore-beacon','repair','deliver-parcel','settle-pressure'].includes(type)){effects.push({x:state.x,y:state.y,time:t,color:type==='restore-beacon'?'#a8ef9e':'#efd49b'});if(effects.length>12)effects.shift();}if(previousZone!==state.zone){path=[];destination=null;nearby=null;focusRing=null;keys.clear();autoWait=3;$('speech').hidden=true;toast(sceneOf(state).name+' · '+Object.keys(exits(state)).length+' connecting passage'+(Object.keys(exits(state)).length===1?'':'s'));$('world').classList.add('arriving');setTimeout(()=>$('world').classList.remove('arriving'),350);}save();updateUI();if(event.memory)say(event.memory);tone(type==='repair'?440:330);return true;}
function updateUI(){document.body.classList.toggle('in-city',state.zone!=='district');$('location-name').textContent=sceneOf(state).name;$('location-kicker').textContent=sceneOf(state).subtitle;$('zone-link').hidden=true;$('minimap-panel').hidden=false;$('quest-title').textContent=state.continuity.draft?'Something unfinished':'What stays with her';$('quest-text').textContent=state.mind.intent;$('quest-step').textContent='Her notebook';document.querySelectorAll('.quest-progress i').forEach((e,i)=>e.classList.toggle('done',i<(state.zone==='district'?state.stage:Math.floor(state.city.visited.length/7*5))));$('gear-count').textContent=state.gear;$('gear-slot').style.opacity=state.gear?'1':'.55';$('mood').textContent=state.mood;$('resolve-fill').style.width=`${Math.round(state.continuity.energy*100)}%`;$('journal-count').textContent=state.events.filter(e=>e.memory).length;$('clock').textContent=ageLabel(state.continuity.age);const e=state.events.at(-1);$('latest-event').innerHTML=`<time>${ageLabel(e?.age??e?.time??0)} · FIELD NOTES</time>${escape(e?.text||'The lanes are quiet.')}`;$('resident-state').textContent=state.continuity.energy<.3?'Tired · carrying unfinished things':state.continuity.beliefs.length?`${state.continuity.beliefs.length} ideas shaped by experience`:'Finding out what matters to her';$('route-list').innerHTML=Object.entries(exits(state)).map(([id,p])=>`<button data-exit="${id}" class="route-button"><span>${p.dir.toUpperCase()}</span> ${escape(p.name)}${p.locked?' · closed':''}</button>`).join('');document.querySelectorAll('[data-exit]').forEach(b=>b.onclick=()=>{if(mode==='watch')setMode('explore');goPlace(b.dataset.exit);});}
function setMode(m){mode=m;pendingDecision=null;path=[];destination=null;autoWait=1.5;keys.clear();$('explore').classList.toggle('selected',m==='explore');$('watch').classList.toggle('selected',m==='watch');updateUI();toast(m==='watch'?'Watching Iona · she’ll choose her next stop':'Explore · WASD, arrow keys, or click to walk');}
function openDialog(html){keys.clear();$('dialog-content').innerHTML=html;if(!$('dialog').open)$('dialog').showModal();}
function closeDialog(){$('dialog').close();keys.clear();canvas.focus({preventScroll:true});}
function actionButton(text,fn,primary=false){const b=document.createElement('button');b.className=`action${primary?' primary':''}`;b.textContent=text;b.onclick=fn;$('dialog-content').querySelector('.dialog-actions').append(b);}
function tryAction(type,payload={}){if(perform(type,payload)){closeDialog();return true;}const thought=unmet(state,type);note(state,thought,'attempt');say(thought);toast('Nothing changes yet.');save();return false;}
function objectDialog(id){const p=activePlaces(state)[id];if(!p)return;if(p.exit){if(p.locked){say('It gives a little, then catches. The bolt is somewhere on the other side.');return;}perform('travel:'+p.dir);return;}
 const seen=studied(state,state.zone,id);const last=state.mind.known[state.zone+':'+id]?.observation;openDialog(`<div class="eyebrow">${escape(sceneOf(state).name.toUpperCase())}</div><h2>${escape(p.name)}</h2><p>${seen?escape(id==='npc'?residentVoice(state,state.zone):last||'The marks of use are easier to see up close.'):'There is more to this than its shape from a distance.'}</p><div class="dialog-actions"></div>`);
 if(!seen){actionButton('Look more closely',()=>{perform('study',{id});objectDialog(id);},true);actionButton('Leave it for now',closeDialog);return;}
 for(const o of continuityOptions(state).filter(o=>o.zone===state.zone&&o.id===id))actionButton(o.type==='life-reflect'?'Sit with what happened':o.type==='life-company'?'Stay and talk':o.type==='life-listen'?'Listen without looking for a fault':o.type==='life-compose'?'Return to the unfinished sketch':o.type==='life-feedback'?'Let them hear the unfinished part':o.type==='life-share'?'Share something she made':'Return to what stayed with her',()=>tryAction(o.type,o.payload),false);
 for(const option of practicalOptions(state,id))actionButton(option.label,()=>tryAction(option.type,option.payload||{}),true);
 if(id==='pump'){if(state.stage===0)actionButton('Follow the knocking sound',()=>tryAction('inspect'),true);else if(state.stage===2)actionButton('Try the spare gear',()=>tryAction('repair'),true);else if(state.stage>=3)actionButton('Listen again',()=>{perform('revisit');closeDialog();say('It has kept the rhythm.');});else actionButton('Turn the wheel by hand',()=>{closeDialog();say('It catches at the missing tooth.');});}
 if(id==='market'&&state.stage===1)actionButton('Keep the loose gear',()=>tryAction('take-gear'),true);
 if(id==='tank')actionButton('Ease the valve',()=>{if(state.stage===3)tryAction('balance');else{closeDialog();say('The pressure is coming from somewhere else.');}},true);
 if(id==='gate')actionButton('Test the winch lever',()=>{if(state.stage===4)tryAction('workshop');else{closeDialog();say(state.stage>=5?'The cage is moving again.':'There is no pull in the line yet.');}},true);
 if(id==='benchwork'&&(state.continuity.draft||state.continuity.works.length))actionButton('Look through her sound sketches',becomingView);
 if(id==='bench')actionButton('Sit for a moment',()=>{perform('rest');closeDialog();});
 if(id==='npc'){
  actionButton('Listen to what they notice',()=>{perform('talk');closeDialog();say(residentVoice(state,state.zone));},true);
  if(state.zone==='lantern'&&!state.life.promised)actionButton('Ask about the wrapped object',()=>{openDialog(`<div class="eyebrow">MARA</div><div class="quote">“A fuse. Edda’s been waiting for it. I haven’t made it across yet.”</div><div class="dialog-actions"></div>`);actionButton('Offer to take it along',()=>tryAction('accept-parcel'),true);actionButton('Another time',closeDialog);});
  if(state.zone==='cable'&&state.life.parcel)actionButton('Show her Mara’s parcel',()=>tryAction('deliver-parcel'),true);
  if(state.life.beacon)actionButton('Ask about the new signal',()=>{closeDialog();say('“Saw the first carriage move a little while ago. Was that your doing?”');});
 }
 if(id==='latch'&&!state.city.shortcut)actionButton('Lift the loose bolt',()=>tryAction('unlatch'),true);
 if(id==='cache'&&!state.city.recovered)actionButton('Keep the ringing coil',()=>tryAction('recover'),true);
 if(id==='regulator')actionButton(state.life.stable?'Listen to the steady note':'Try the two wheels',()=>state.life.stable?(closeDialog(),say('It holds its note now.')):regulatorDialog(),true);
 actionButton('Step away',closeDialog);
}
function regulatorDialog(){openDialog(`<div class="eyebrow">A SHUDDER IN THE PIPES</div><h2>Two wheels. One rhythm.</h2><div class="pressure-gauge"><div class="safe-band"></div><i id="needle"></i><span id="pressure-reading"></span></div><p class="detail">The green paint is worn, but still visible on the dial.</p><label class="dial-row">Intake <input id="intake" type="range" min="0" max="6" step="1" value="${state.life.intake}"><output id="intake-value">${state.life.intake}</output></label><label class="dial-row">Vent <input id="vent" type="range" min="0" max="6" step="1" value="${state.life.vent}"><output id="vent-value">${state.life.vent}</output></label><div class="dialog-actions"></div>`);const paint=()=>{const value=state.life.pressure;$('needle').style.left=Math.max(0,Math.min(100,value/90*100))+'%';$('pressure-reading').textContent=value;};paint();for(const id of ['intake','vent'])$(id).oninput=()=>$(id+'-value').textContent=$(id).value;actionButton('Try this adjustment',()=>{const ok=perform('probe',{intake:Number($('intake').value),vent:Number($('vent').value)});if(!ok)toast('That setting has the same note as before.');paint();},true);actionButton('Secure the mechanism',()=>tryAction('settle-pressure'));actionButton('Step back',closeDialog);}
function discoveriesView(){openDialog(`<div class="eyebrow">THINGS IONA HAS PUT TOGETHER</div><h2>A growing understanding.</h2><div class="skill-list">${state.life.skills.map(k=>`<span>${escape(k)}</span>`).join('')}</div><p class="detail">What she has noticed, tried, and kept.</p>${[...state.mind.notes].reverse().map(n=>`<article class="ledger-entry"><time>${clock(n.time)} · ${escape(n.kind.toUpperCase())}</time><p>${escape(n.text)}</p></article>`).join('')}`);}
function becomingView(){const c=state.continuity;const memory=id=>c.memories.find(m=>m.id===id);const evidence=ids=>ids.map(memory).filter(Boolean).map(m=>`<li>${escape(m.text)} <small>${ageLabel(m.at)}</small></li>`).join('');openDialog(`<div class="eyebrow">IONA · ${ageLabel(c.age)}</div><h2>Still becoming.</h2><p class="character-core">She notices what catches, keeps things others discard, and finds it easier to offer help than to ask for company.</p><p class="detail">Experiences can complicate who she is. They do not replace her overnight.</p><div class="journal-tabs"><button id="back-memories">Her memories</button><button id="leave-thought">Leave a thought</button></div><h3>What she is carrying</h3>${Object.values(c.threads).map(th=>`<article class="thread-card"><span>${c.age>=th.due?'ON HER MIND':'LEFT TO SETTLE'}</span><p>${escape(th.title)}</p><small>Since ${ageLabel(th.opened)}</small></article>`).join('')||'<p class="detail">The first things she cares about will come from what happens here.</p>'}<h3>Things she is beginning to believe</h3>${c.beliefs.map(b=>`<details class="belief"><summary>${escape(b.text)}</summary><p class="detail">Experiences behind this idea:</p><ul>${evidence(b.evidence)}</ul></details>`).join('')||'<p class="detail">A single success does not make a conviction. She needs more to go on.</p>'}<h3>People becoming familiar</h3><div class="relationship-list">${Object.values(c.relationships).filter(r=>r.familiarity).map(r=>`<article><b>${escape(r.name)}</b><p>${r.trust>.5?'Someone she seeks out':r.trust>.25?'A little easier to be herself':'Still finding a way to talk'}</p><small>${r.familiarity} shared encounters</small></article>`).join('')||'<p class="detail">She has not stopped to know anyone yet.</p>'}</div><h3>Work that belongs to her</h3>${c.draft?`<article class="thread-card"><span>UNFINISHED · SOUND SKETCH</span><p>${c.draft.phase==='feedback'?'It works as a sequence of sounds. She is not sure it says anything yet.':'A neighbour heard something she missed. She is letting it settle before returning.'}</p></article>`:''}${[...c.works].reverse().map(w=>`<article class="work-card"><span class="sound-wave">▁ ▃ ▂ ▆ ▂ ▁ ▄ ▂</span><h4>${escape(w.title)}</h4><p>Arrangement ${w.revision} · ${w.sources.length} remembered sounds${w.feedback?' · shaped with '+escape(w.feedback):''}</p><button class="action play-work" data-work="${w.id}">Listen to her arrangement</button><small>${ageLabel(w.at)} · ${w.shared.length?`Shared with ${w.shared.map(z=>escape(residentVoiceName(z))).join(', ')}`:'Not shared yet'}</small></article>`).join('')||(!c.draft?'<p class="detail">There is no assignment here. Something may grow out of what she keeps noticing.</p>':'')}<h3>After sitting with it</h3>${[...c.reflections].reverse().slice(0,8).map(r=>`<article class="ledger-entry"><time>${ageLabel(r.at)}</time><p>${escape(r.text)}</p></article>`).join('')||'<p class="detail">She has not had enough distance from this evening yet.</p>'}<p class="detail">Her life is saved in this browser. Time matures her concerns between visits; she takes action while you are here. Memory and preference changes use local rules in this build.</p>`);$('back-memories').onclick=()=>journalView();$('leave-thought').onclick=thoughtView;document.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>playWork(Number(b.dataset.work)));}
let sketchAudio=null,sketchPlayingUntil=0;
async function playWork(id){const w=state.continuity.works.find(w=>w.id===id);if(!w?.notes?.length)return;try{sketchAudio??=new AudioContext();await sketchAudio.resume();if(sketchAudio.currentTime<sketchPlayingUntil)return;const start=sketchAudio.currentTime+.1;for(const n of w.notes){const o=sketchAudio.createOscillator(),g=sketchAudio.createGain();o.type='sine';o.frequency.value=n.frequency;o.connect(g);g.connect(sketchAudio.destination);const at=start+n.beat*.38;g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(.09,at+.025);g.gain.exponentialRampToValueAtTime(.0001,at+n.duration);o.start(at);o.stop(at+n.duration+.1);sketchPlayingUntil=Math.max(sketchPlayingUntil,at+n.duration);}toast('Her remembered street notes, with a little room between them.');}catch{toast('Audio is unavailable in this browser.');}}
function residentVoiceName(z){return {crossing:'Orin',lantern:'Mara',violet:'Ves',cable:'Edda'}[z]||z;}
function journalView(tab='memories'){const events=state.events.filter(e=>tab==='history'||e.memory).slice().reverse();openDialog(`<div class="eyebrow">${tab==='memories'?'IONA’S NOTEBOOK':'THE OBSERVER · COMMITTED EVENTS'}</div><h2>${tab==='memories'?'Things worth keeping.':'What happened here.'}</h2><div class="journal-tabs"><button id="memories-tab" class="${tab==='memories'?'selected':''}">Her memories</button><button id="becoming-tab">Becoming</button><button id="discoveries-tab">Connections</button><button id="history-tab" class="${tab==='history'?'selected':''}">World history</button></div>${events.map(e=>`<article class="ledger-entry"><time>${ageLabel(e.age??e.time)}</time><p class="${tab==='memories'?'memory':''}">${escape(tab==='memories'?e.memory:e.text)}</p></article>`).join('')}<p class="detail">${tab==='history'?'The observer only reads events that have already happened.':'Experiences, relationships, and unfinished work persist on this device.'}</p><div class="dialog-actions"><button class="action" id="export">Export world history</button></div>`);$('becoming-tab').onclick=becomingView;$('discoveries-tab').onclick=discoveriesView;$('memories-tab').onclick=()=>journalView('memories');$('history-tab').onclick=()=>journalView('history');$('export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='gutterlight-world.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};}
function mapView(){openDialog(`<div class="eyebrow">STREETS YOU HAVE WALKED</div><h2>The Lower Undercity</h2><canvas id="city-map" width="640" height="350" style="width:100%;border:1px solid #66794c;border-radius:4px"></canvas><p class="detail">Bright marker: you. Dim markers: unexplored passages. A broken line marks the bolted service gate. ${state.city.visited.length} of 7 neighborhoods discovered.</p><div class="dialog-actions">${Object.entries(exits(state)).map(([id,p])=>`<button class="action" data-route="${id}">${p.dir.toUpperCase()} · ${escape(p.name)}${p.locked?' (bolted shortcut)':''}</button>`).join('')}</div>`);drawCityMap($('city-map'),state,true);document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{setMode('explore');closeDialog();goPlace(b.dataset.route);});}
function thoughtView(){openDialog('<div class="eyebrow">A THOUGHT LEFT BY THE LANTERN</div><h2>Something she might carry.</h2><p>A question, not an instruction. She will read it when she returns, and may take time to make anything of it.</p><div class="dialog-actions"></div>');for(const [influence,text]of [['care','Who would you visit with nothing to bring?'],['curiosity','What would you make just for yourself?'],['independence','Could you leave a working thing alone?']])actionButton(text,()=>{if(leaveThought(state,influence)){save();closeDialog();toast('A thought left beside the lantern.');}else toast('Let the last thought have a little time.');});actionButton('Leave nothing for now',closeDialog);}
function giftView(){if(state.zone!=='district'){toast('Leave gifts in the Foundry Lanes, where they can grow.');return;}openDialog(`<div class="eyebrow">A VISITOR’S SMALL KINDNESS</div><h2>Leave something growing.</h2><p>${state.gift?'A moss cutting already lives in these lanes. Iona will remember the kindness.':'Leave a tin of luminous moss beside Iona. It will stay in this world, and she may decide to look after it.'}</p><p class="detail">Visitor gifts are saved on this device in this prototype.</p><div class="dialog-actions"></div>`);actionButton('Leave a thought',thoughtView);actionButton(state.gift?'Return to the lanes':'Leave a moss cutting',()=>{if(!state.gift){perform('gift');toast('A gift left in the lanes');}closeDialog();},true);}
function bagView(){openDialog(`<div class="eyebrow">IONA’S SATCHEL</div><h2>A few useful things.</h2><p>${state.gear?'⚙ Brass gear · 1<br>A sound eight-tooth gear, waiting for the pump.':state.stage>=3?'The spare gear is part of the pump now.':'There is room for something worth keeping.'}</p><p>${state.city.recovered&&!state.life.coilUsed?'Resonance coil · rings when touched<br>':''}${state.life.scrap} workable copper · ${state.life.wire} wire coils<br>${state.life.parcel?'Wrapped fuse · meant for Edda<br>':''}Brass wrist tool · always carried<br>Leather notebook · ${state.events.filter(e=>e.memory).length} memories</p><div class="dialog-actions"></div>`);actionButton('Read the notebook',()=>journalView());actionButton('Return to the lanes',closeDialog,true);}
function helpView(){openDialog(`<div class="eyebrow">WELCOME TO GUTTERLIGHT</div><h2>A little life. A big world.</h2><p>Explore a handmade industrial district as Iona, or choose <strong>Watch Iona</strong> and follow her curiosity. Walk off the end of an open street to enter the next neighborhood. Alleys branch, loop back, or end at walls. Machines have habits. People notice things. Let Iona look, listen, and try what she learns. Press M to see the streets you have discovered. Your discoveries and shortcut persist between visits.</p><p><strong>WASD / arrow keys</strong> · move<br><strong>Click / tap the ground</strong> · walk there<br><strong>E</strong> · interact nearby<br><strong>J / B / M / G</strong> · journal / satchel / map / gift<br><strong>Escape</strong> · close a panel</p><p class="detail">Playable prototype. Iona is a fictional autonomous character using a local symbolic planner, remembered observations, and composable skill rules in this build; live AI is not connected. Concerns mature over real hours and days, including between visits. Iona acts while this page is visible; no conversations or accomplishments are invented while it is closed. Memories, relationships, and evolving preferences are stored on this device. This is not a server-running life or a live language-model character. The observer reports committed events.</p><div class="dialog-actions"></div>`);actionButton('Return to the lanes',closeDialog,true);actionButton('Start a fresh world',()=>{openDialog('<div class="eyebrow">START AGAIN</div><h2>A new evening?</h2><p>This will erase Iona’s memories and your progress on this device. Export the history from the journal first if you want to keep it.</p><div class="dialog-actions"></div>');actionButton('Keep this world',closeDialog,true);actionButton('Erase and begin again',()=>{state=initialState();path=[];destination=null;mode='explore';setMode('explore');save();updateUI();closeDialog();});});}
function route(x,y){return streetRoute(state,x,y);}
function goPlace(id){const p=activePlaces(state)[id];if(!p)return;path=route(p.x,p.y);destination=id;focusRing={x:p.x,y:p.y,until:t+2};}
function autoAct(id){const d=pendingDecision;pendingDecision=null;if(d&&d.id===id){perform(d.type,d.payload||{});autoWait=d.type.startsWith('life-')?18:d.type==='probe'?2.5:d.type==='study'?2:4;}}
function autoStep(dt){if(mode!=='watch'||path.length||$('dialog').open)return;autoWait-=dt;if(autoWait>0)return;perceive(state,activePlaces(state));const decision=decide(state,activePlaces(state));if(!decision){autoWait=5;return;}rememberDecision(state,decision);updateUI();if(decision.type==='pause'){pendingDecision=null;autoWait=decision.wait||30;return;}pendingDecision=decision;goPlace(decision.id);if(!path.length){autoAct(decision.id);destination=null;}}
function nearbyPlace(){let result=null,dist=85;for(const [id,p] of Object.entries(activePlaces(state))){const d=Math.hypot(state.x-p.x,state.y-p.y);if(d<dist){dist=d;result=id;}}return result;}
function move(dt){let dx=0,dy=0,distanceLimit=Infinity;const input=mode==='explore'&&!$('dialog').open; if(input){dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0);dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);}if(dx||dy){path=[];destination=null;}else if(path.length){const p=path[0],d=Math.hypot(p.x-state.x,p.y-state.y);if(d<4){state.x=p.x;state.y=p.y;path.shift();}else{dx=(p.x-state.x)/d;dy=(p.y-state.y)/d;distanceLimit=d;}}moving=!!(dx||dy)&&!$('dialog').open;if(moving){const l=Math.hypot(dx,dy);dx/=l;dy/=l;const speed=keys.has('shift')?235:155;const step=Math.min(speed*dt,distanceLimit),nx=state.x+dx*step,ny=state.y+dy*step;if(canWalk(state,nx,state.y))state.x=nx;if(canWalk(state,state.x,ny))state.y=ny;dir=Math.abs(dx)>Math.abs(dy)*1.3?(dx>0?1:3):(dy>0?0:2);frame=Math.floor(t*8)%4;}
 if(!path.length&&destination&&!$('dialog').open){const id=destination;destination=null;if(id==='gift'){perform('notice-gift');autoWait=6;}else if(mode==='watch')autoAct(id);else if(nearbyPlace()===id)objectDialog(id);}
 const crossing=crossedExit(state);if(crossing){perform('travel:'+activePlaces(state)[crossing].dir);return;}nearby=nearbyPlace();if(state.gift&&!state.gift.noticed&&state.elapsed>5)perform('notice-gift');}
function resize(){width=innerWidth;height=innerHeight;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
function transform(){scale=Math.max(width/W,height/H);const ww=W*scale,wh=H*scale;ox=Math.min(0,Math.max(width-ww,width*.5-state.x*scale));oy=Math.min(0,Math.max(height-wh,height*.6-state.y*scale));}
function screen(x,y){return {x:x*scale+ox,y:y*scale+oy};}
