async function toggleSound(){try{if(!ambient){ambient=new AudioContext();const master=ambient.createGain();master.gain.value=.022;master.connect(ambient.destination);for(const freq of [55,82.4,110]){const o=ambient.createOscillator();o.type='sine';o.frequency.value=freq;o.connect(master);o.start();}const buffer=ambient.createBuffer(1,ambient.sampleRate*3,ambient.sampleRate);const d=buffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*.25;const noise=ambient.createBufferSource(),filter=ambient.createBiquadFilter();filter.type='lowpass';filter.frequency.value=420;noise.buffer=buffer;noise.loop=true;noise.connect(filter);filter.connect(master);noise.start();}soundOn=!soundOn;if(soundOn)await ambient.resume();else await ambient.suspend();$('sound').style.color=soundOn?'#d6e8a6':'';$('sound').setAttribute('aria-label',soundOn?'Mute ambient sound':'Enable ambient sound');toast(soundOn?'Ambient sound on · pipes, hum, and evening air':'Ambient sound off');}catch{toast('Audio is unavailable in this browser.');}}
